// Lot 41 piste 2 (38 C1 à la voix) — V1 « J'ai compris », V2 « Non, c'est pas ça », V3 échec parlé.
// Real S24 captures: fixtures/s24-2026-10-11/ (core #129: v2 decisions + harness shortlists, terminal
// receipts, Orange run). HS3 presentation samples are copied verbatim from core #127
// (fixtures/s24-2026-10-11c, generated by playbooks #72 on the same real captures) from #127, now merged; the Maxit not-submitted shape is the payment adapter contract (test-maxit-topup-payment-adapter).
// No model, no network, no audio, no transcript persisted.
const {test}=require("node:test");
const assert=require("node:assert/strict");
const fs=require("fs"),os=require("os"),path=require("path"),http=require("http");

const root=fs.mkdtempSync(path.join(os.tmpdir(),"voice-understanding-"));
os.homedir=()=>root;process.env.OPENCLAW_STATE_DIR=path.join(root,"state");
process.env.CLAW_VOICE_RELAY_CONFIG=path.join(root,"missing-relay.json");
// ADR 02/11 « le cerveau partout », step 3: Claw Live and the relay send every turn to the brain, so the realignment
// gestures, Round Learning capture and capability-receipt speech of those surfaces are retired. What remains here is
// the receipt speech library itself (planVoiceSpeech, voiceReceiptProjection) and the gesture list it still exports.

const fx=(name)=>JSON.parse(fs.readFileSync(path.join(__dirname,"..","fixtures","s24-2026-10-11",name),"utf8"));
const RES=fx("hs3-resolution-slots-shortlist.json");
const TERM=fx("hs3-terminal-receipts.json").families;
const ORANGE=fx("o7-o8-orange-20261010-0941.json");
const m=require("../dist/companion/voiceUnderstanding.js");
const {VoiceTurnProtocol}=require("../dist/companion/voiceTurnProtocol.js");

const fromResolution=(key,extra={})=>{const r=RES.resolutions[key];return {success:true,text:r.text,capability:r.capability,decision:r.decision,harness:r.harness,confirmation_required:r.decision.confirmationRequired,...extra};};
const orangeEnvelope=()=>({success:true,...JSON.parse(JSON.stringify(ORANGE.resolution_now.gemini_claw)),execution:{state:"completed",result:ORANGE.client_received_result}});
// HS3 presentations (copied from core #127 fixture s24-2026-10-11c/hs3-presentations-from-captures.json).
const HS3={
  topup_fr:{version:1,locale:"fr",status:"info",label:"Recharger mon numéro",title:"Résultat à vérifier",rows:[],spoken:"Ta confirmation est attendue avant de poursuivre.",primary:{label:"Terminer",action:"done"},effect:{debited:"unknown",source:"receipt"},meta:{capability:"payment.owner_native"},understood:{capability:"payment.owner_native",label:"Recharger mon numéro",slots:{operator:"orange",amountTnd:"5",beneficiary:"owner"},text:"Compris : Recharger mon numéro · Orange · 5 DT · ta ligne"},alternatives:[]},
  topup_en:{version:1,locale:"en",status:"info",label:"Top up my number",title:"Result to verify",rows:[],spoken:"Your confirmation is needed before proceeding.",primary:{label:"Done",action:"done"},effect:{debited:"unknown",source:"receipt"},meta:{capability:"payment.owner_native"},understood:{capability:"payment.owner_native",label:"Top up my number",slots:{operator:"orange",amountTnd:"5",beneficiary:"owner"},text:"Understood: Top up my number · Orange · 5 TND · your line"},alternatives:[]},
  effect_unknown_fr:{version:1,locale:"fr",status:"error",label:"Shared native owner confirmation for payments",title:"Résultat à vérifier",rows:[],spoken:"La demande n’a pas abouti. Consulte le détail avant toute nouvelle action.",primary:{label:"Terminer",action:"done"},effect:{debited:"unknown",source:"receipt"},meta:{capability:"payment.owner_native"},understood:{capability:"payment.owner_native",label:"Shared native owner confirmation for payments",slots:{},text:"Compris : Shared native owner confirmation for payments"},alternatives:[],failure:{step:"Exécution du paiement",stepId:"execution_error",reason:"L’effet du paiement n’est pas vérifié.",notDone:{code:"unknown"}}},
  blocked_after_dispatch_fr:{version:1,locale:"fr",status:"error",label:"Shared native owner confirmation for payments",title:"Résultat à vérifier",rows:[],spoken:"La demande n’a pas abouti. Consulte le détail avant toute nouvelle action.",primary:{label:"Terminer",action:"done"},effect:{debited:"unknown",source:"receipt"},meta:{capability:"payment.owner_native"},understood:{capability:"payment.owner_native",label:"Shared native owner confirmation for payments",slots:{},text:"Compris : Shared native owner confirmation for payments"},alternatives:[],failure:{step:"Exécution du paiement",stepId:"execution_error",reason:"La cause n’est pas établie par le reçu.",notDone:{code:"unknown"}}},
  expired_not_submitted_fr:{version:1,locale:"fr",status:"error",label:"Shared native owner confirmation for payments",title:"Résultat à vérifier",rows:[],spoken:"La demande n’a pas abouti. Consulte le détail avant toute nouvelle action.",primary:{label:"Terminer",action:"done"},effect:{debited:"unknown",source:"receipt"},meta:{capability:"payment.owner_native"},understood:{capability:"payment.owner_native",label:"Shared native owner confirmation for payments",slots:{},text:"Compris : Shared native owner confirmation for payments"},alternatives:[],failure:{step:"Étape non établie",stepId:"unknown",reason:"La cause n’est pas établie par le reçu.",notDone:{code:"payment_not_submitted",text:"Rien n’a été envoyé au fournisseur."}}},
};
// Real S24 PaymentRecord (core #127 s24-2026-10-11c, Topnet 10/04): blocked AFTER financial dispatch.
const BLOCKED_AFTER_DISPATCH={adapterId:"topnet",mode:"live",state:"blocked",reasonCode:"browser_context_unavailable",executorAttempts:1,financialSubmissionAttempted:true,hasReceipt:false};
const CODE=/\b[a-z]+_[a-z0-9_]+\b/;

test("V1 real decisions: transaction always announced, confident read/write silent, low confidence announced",()=>{
  for(const key of ["r8","r11"]){
    const s=m.planVoiceSpeech(fromResolution(key),{locale:"fr"});
    assert.equal(s.phase,"transaction");assert.match(s.verbatim,/^J'ai compris : payment owner native · telecom orange topup own number\.$/);
  }
  assert.equal(m.planVoiceSpeech(fromResolution("r4")).verbatim,null,"agenda move at 0.947: no preamble");
  assert.equal(m.planVoiceSpeech(fromResolution("r9")).verbatim,null);
  const r3=m.planVoiceSpeech(fromResolution("r3"));
  assert.equal(r3.phase,"read_low_confidence");assert.match(r3.verbatim,/^J'ai compris : device assistance/);
  assert.equal(m.planVoiceSpeech(orangeEnvelope()).verbatim,null,"Orange balance at confidence 1");
  assert.equal(m.planVoiceSpeech(TERM.factures.receipt.envelope).verbatim,null,"bills at 0.923");
  const low=TERM.factures.receipt.envelope;const lowered={...low,harness:{...low.harness,confidence:0.52}};
  assert.equal(m.planVoiceSpeech(lowered).verbatim,null,"an envelope without canonical decision/presentation cannot invent understanding from capability");
  assert.equal(m.HARNESS_TRUST_THRESHOLD,0.6);
});

test("V1 HS3 understood sentence is spoken verbatim (never rephrased)",()=>{
  const fr=m.planVoiceSpeech(fromResolution("r11",{presentation:HS3.topup_fr}),{locale:"fr"});
  assert.equal(fr.verbatim,"J'ai compris : Recharger mon numéro · Orange · 5 DT · ta ligne.");
  const en=m.planVoiceSpeech(fromResolution("r11",{presentation:HS3.topup_en}),{locale:"fr"});
  assert.equal(en.verbatim,"I understood: Top up my number · Orange · 5 TND · your line.");
  // /v1/runs shape (top-level understood) is read the same way.
  const top=m.planVoiceSpeech(fromResolution("r11",{presentation:HS3.topup_fr,understood:HS3.topup_fr.understood}),{locale:"fr"});
  assert.equal(top.verbatim,fr.verbatim);
});

test("V1 CLARIFY: real needs_parameter for the top-up and a CLARIFY decision announce what was understood",()=>{
  const needs=RES.validated_slots.cases[1].needs_parameter;
  const s=m.planVoiceSpeech(fromResolution("r8",{execution:{state:"completed",result:needs}}),{locale:"fr"});
  assert.match(s.verbatim,/^J'ai compris : /);assert.equal(s.failure,undefined);
  const clarify={...orangeEnvelope(),decision:{...ORANGE.decision_envelope,type:"CLARIFY",confidence:0.9}};
  assert.equal(m.planVoiceSpeech(clarify).phase,"clarify");
});

test("V3 HS3 failure: step and readable reason; « rien n'a été débité » only with notDone=payment_not_submitted",()=>{
  const unknown=m.planVoiceSpeech(fromResolution("r11",{success:false,presentation:HS3.effect_unknown_fr}));
  assert.equal(unknown.phase,"failure");
  assert.match(unknown.verbatim,/Ça n'a pas abouti à l'étape « Exécution du paiement » : l’effet du paiement n’est pas vérifié\./);
  assert.doesNotMatch(unknown.verbatim,/débité/);
  const blocked=m.planVoiceSpeech(fromResolution("r11",{success:false,presentation:HS3.blocked_after_dispatch_fr}));
  assert.doesNotMatch(blocked.verbatim,/débité/,"blocked after dispatch proves nothing");
  const expired=m.planVoiceSpeech(fromResolution("r11",{success:false,presentation:HS3.expired_not_submitted_fr}));
  assert.match(expired.verbatim,/Ça n'a pas abouti : la cause n’est pas établie par le reçu\. Rien n'a été débité\.$/);
  for(const s of [unknown,blocked,expired])assert.doesNotMatch(s.verbatim,CODE);
});

test("V3 fallback on decision v2: readable reason, never a code; real blocked-after-dispatch never claims no debit",()=>{
  const maxit={...fromResolution("r11"),success:false,execution:{state:"completed",result:{state:"blocked",reasonCode:"payment_not_submitted",reasonDetail:"maxit_order_creation_failed"}}};
  const s=m.planVoiceSpeech(maxit);
  assert.match(s.failure,/étape « paiement » : la commande n'a pas pu être créée chez l'opérateur\./);
  assert.equal(s.noDebit,"Rien n'a été débité.");
  const real=m.planVoiceSpeech({...fromResolution("r11"),success:false,execution:{state:"completed",result:{payment:BLOCKED_AFTER_DISPATCH}}});
  assert.equal(real.phase,"failure");assert.equal(real.noDebit,undefined);assert.doesNotMatch(real.verbatim,CODE);
  const bridge=m.planVoiceSpeech({success:false,error:"capability_bridge_unavailable"});
  assert.equal(bridge.verbatim,"Ça n'a pas abouti à l'étape « exécution » : le service Claw n'est pas joignable.");
  const odd=m.planVoiceSpeech({...orangeEnvelope(),execution:{state:"failed",error:"maxit_http_400_some_internal_code"}});
  assert.match(odd.verbatim,/la cause n'est pas établie par le reçu/);assert.doesNotMatch(odd.verbatim,CODE);
  assert.equal(m.planVoiceSpeech({...orangeEnvelope(),execution:{state:"failed"}},{locale:"en"}).verbatim,"It did not go through at the “execution” step: the receipt does not establish the cause.");
});

test("V2 gestures: versioned FR/EN/derja/arabizi list, deterministic, 2-minute window",()=>{
  const p=m.VOICE_REALIGNMENT_PHRASES;
  assert.equal(p.version,"voice-realign-v1-20261011");assert.equal(p.windowMs,120000);
  assert.equal(p.provenance.derja,"authored_pending_amine");assert.equal(p.provenance.arabizi,"authored_pending_amine");
  const now=1_800_000_000_000,at=now-30_000;
  for(const lang of ["fr","en","derja","arabizi"])for(const phrase of p[lang])assert.ok(m.isVoiceRealignment(phrase,at,now),lang+": "+phrase);
  for(const said of ["Non, c’est pas ça !","Samantha, non non c'est pas ça","NON CE N'EST PAS ÇA.","la mouch haka samantha","لا موش هكا؟","No, that's not it."])
    assert.ok(m.isVoiceRealignment(said,at,now),said);
  for(const said of ["recharge mon numéro Orange","non","c'est pas ça le solde que je veux","pas ça mais le forfait","mon solde","", "x".repeat(200)])
    assert.equal(m.isVoiceRealignment(said,at,now),false,said);
  assert.equal(m.isVoiceRealignment("c'est pas ça",now-120_001,now),false,"outside the window");
  assert.equal(m.isVoiceRealignment("c'est pas ça",undefined,now),false,"no previous turn");
});

test("Verified receipt verbalization imposes the text, and the protocol checks it was spoken first",async()=>{
  const sent=[],events=[];
  const p=new VoiceTurnProtocol(1,"epoch-a",(v)=>sent.push(v),(v)=>events.push(v));
  const ctl=(kind,body)=>p.receive({warmControl:{[kind]:{operationId:"op-"+kind+"-"+(body.turnId||""),sessionEpoch:"epoch-a",...body}}});
  ctl("turnStart",{turnId:"t1",firstSample:0});ctl("turnEnd",{turnId:"t1",lastSampleExclusive:0});
  ctl("transcriptFinal",{turnId:"t1",source:"android_speech_service",text:"Recharge mon numéro Orange de 5 dinars"});
  const receipt={...fromResolution("r11",{presentation:HS3.topup_fr}),voice:m.planVoiceSpeech(fromResolution("r11",{presentation:HS3.topup_fr}))};
  await p.execute("t1","Recharge mon numéro Orange de 5 dinars",async()=>receipt);
  p.provider({serverContent:{turnComplete:true}});
  p.receiptReply("t1");
  const instruction=sent.at(-1).clientContent.turns[0].parts[0].text;
  assert.ok(instruction.includes("Start your answer with exactly this text, word for word"));
  assert.ok(instruction.includes("«J'ai compris : Recharger mon numéro · Orange · 5 DT · ta ligne.»"));
  p.provider({serverContent:{outputTranscription:{text:"J'ai compris : Recharger mon numéro · Orange · 5 DT · ta ligne. "}}});
  p.provider({serverContent:{outputTranscription:{text:"Je t'ouvre la confirmation."}}});
  p.provider({serverContent:{turnComplete:true}});
  const check=events.map(e=>e.warmEvent?.payload?.voiceVerbatim).filter(Boolean);
  assert.deepEqual(check,[{imposed:true,spoken:true}]);
  // A rephrased answer is flagged.
  const sent2=[],events2=[];const q=new VoiceTurnProtocol(1,"epoch-b",(v)=>sent2.push(v),(v)=>events2.push(v));
  const ctl2=(kind,body)=>q.receive({warmControl:{[kind]:{operationId:"op-"+kind,sessionEpoch:"epoch-b",...body}}});
  ctl2("turnStart",{turnId:"t2",firstSample:0});ctl2("turnEnd",{turnId:"t2",lastSampleExclusive:0});
  ctl2("transcriptFinal",{turnId:"t2",source:"android_speech_service",text:"Recharge mon numéro Orange de 5 dinars"});
  await q.execute("t2","Recharge mon numéro Orange de 5 dinars",async()=>receipt);
  q.provider({serverContent:{outputTranscription:{text:"D'accord, je recharge 5 dinars."}}});
  q.provider({serverContent:{turnComplete:true}});
  assert.deepEqual(events2.map(e=>e.warmEvent?.payload?.voiceVerbatim).filter(Boolean),[{imposed:true,spoken:false}]);
});

