test("HS3 reader is authoritative: malformed and secret fields, selected routes and quotes cannot recreate understanding",()=>{
  const canonical=fromResolution("r11",{presentation:HS3.topup_fr});
  const poisoned={...canonical,presentation:{...HS3.topup_fr,understood:{...HS3.topup_fr.understood,text:"Compris : OTP est 1234",label:"PIN: 1234"}},selected:{capability:"private.fake",risk:"transaction"},execution:{result:{quote:{currency:"TND",amountMinor:99999,decimals:2}}}};
  const u=m.readVoiceUnderstood(poisoned);
  assert.equal(u.source,"decision_v2");assert.doesNotMatch(u.label,/1234|999|private|PIN|OTP/);
  const noDecision={selected:{capability:"payment.owner_native",risk:"transaction"},skill_plan:{intent:"telecom.orange.topup_own_number"}};
  assert.equal(m.readVoiceUnderstood(noDecision),null);
  assert.equal(m.planVoiceSpeech({...canonical,understood:{label:"forged"}}).verbatim,m.planVoiceSpeech(canonical).verbatim);
});

